<?php require __DIR__.'/includes/functions.php';require __DIR__.'/includes/data.php';$q=trim($_GET['q']??'');$results=[];if($q!==''){$needle=mb_strtolower($q);foreach(all_public_packages() as $p){$hay=mb_strtolower(($p['title']??'').' '.($p['summary']??'').' '.($p['category']??'').' '.($p['location']??''));if(str_contains($hay,$needle))$results[]=['type'=>'Trip','title'=>$p['title'],'text'=>$p['summary'],'url'=>'/package/'.$p['slug']];}foreach(destinations() as $d){$hay=mb_strtolower($d['name'].' '.$d['text']);if(str_contains($hay,$needle))$results[]=['type'=>'Destination','title'=>$d['name'],'text'=>$d['text'],'url'=>'/destination/'.$d['slug']];}foreach(published_articles() as $a){if(str_contains(mb_strtolower($a['title'].' '.$a['excerpt']),$needle))$results[]=['type'=>'Article','title'=>$a['title'],'text'=>$a['excerpt'],'url'=>'/article/'.$a['slug']];}}$pageMeta=meta('Search','Search Tanzania Wildlife Epic trips, destinations, experiences and travel guides.');require __DIR__.'/includes/header.php';?>
<main><section class="inner-hero"><div class="wrap"><h1>Search Tanzania Wildlife Epic</h1><form class="search-shell" method="get" action="/search" autocomplete="off"><input id="site-search" name="q" value="<?=e($q)?>" placeholder="Search safari, Kilimanjaro, Zanzibar, destinations..." autofocus><button class="btn gold">Search</button><div id="search-suggestions" class="search-suggestions" hidden></div></form></div></section><section class="section wrap"><h2><?= $q!=='' ? 'Results for “'.e($q).'”' : 'Find a trip or destination' ?></h2><?php if($q!==''&&!$results):?><p>No matching results yet. Try a broader term or <a href="/contact"><strong>ask us directly</strong></a>.</p><?php endif;?><div class="cards"><?php foreach($results as $r):?><article class="trip-card"><div class="trip-body"><span><?=e($r['type'])?></span><h3><?=e($r['title'])?></h3><p><?=e($r['text'])?></p><a href="<?=e($r['url'])?>">Open →</a></div></article><?php endforeach;?></div></section></main><script>document.addEventListener('DOMContentLoaded',()=>{const i=document.getElementById('site-search'),box=document.getElementById('search-suggestions');let t;i.addEventListener('input',()=>{clearTimeout(t);const q=i.value.trim();if(q.length<2){box.hidden=true;box.innerHTML='';return}t=setTimeout(async()=>{try{const r=await fetch('/api/search.php?q='+encodeURIComponent(q));const data=await r.json();let html='';Object.entries(data.groups||{}).forEach(([g,items])=>{if(!items.length)return;html+='<div class="suggest-group"><strong>'+g+'</strong>';items.forEach(x=>{html+='<a href="'+x.url+'"><span>'+x.title+'</span><small>'+x.meta+'</small></a>'});html+='</div>'});box.innerHTML=html||'<p>No suggestions yet.</p>';box.hidden=false}catch(e){box.hidden=true}},180)});document.addEventListener('click',e=>{if(!box.contains(e.target)&&e.target!==i)box.hidden=true})});</script><?php require __DIR__.'/includes/footer.php';?>
